-- Explicit dependency plan: 195 retired-data deletes, one inspected cyclic FK.
set local lock_timeout='10s';set local statement_timeout='120s';
select set_config('home.retention_maintenance','on',true);
do $$begin if not exists(select 1 from public.review_corpus_policy where paused and not enabled and backup_verified_sha256 is not null) then raise exception 'VERIFIED_BACKUP_AND_BARRIER_REQUIRED';end if;
if exists(select 1 from cron.job where active) then raise exception 'CRON_NOT_PAUSED';end if;end $$;
-- Seed text-free reimport keys and textless aggregates before deleting sources.
insert into private.review_seen_keys(establishment_id,external_key_sha256,first_published_at,first_seen_at)
select establishment_id,encode(extensions.digest(btrim(external_review_id),'sha256'),'hex'),min(published_at),min(created_at) from public.reviews group by establishment_id,btrim(external_review_id) on conflict do nothing;
insert into public.review_observation_totals(establishment_id,organization_id,observed_reviews,observed_textless_reviews,textless_star_counts,first_observed_at)
select r.establishment_id,r.organization_id,count(*),count(*) filter(where public.review_usable_text(r.original_text,r.text) is null),jsonb_build_object('1',count(*) filter(where public.review_usable_text(r.original_text,r.text) is null and rating=1),'2',count(*) filter(where public.review_usable_text(r.original_text,r.text) is null and rating=2),'3',count(*) filter(where public.review_usable_text(r.original_text,r.text) is null and rating=3),'4',count(*) filter(where public.review_usable_text(r.original_text,r.text) is null and rating=4),'5',count(*) filter(where public.review_usable_text(r.original_text,r.text) is null and rating=5)),min(created_at)
from (select distinct on(establishment_id,btrim(external_review_id)) * from public.reviews order by establishment_id,btrim(external_review_id),updated_at desc,id) r group by r.establishment_id,r.organization_id;
insert into private.retired_generation_keys select id,source_run_id,now(),(select epoch from public.review_corpus_policy) from public.report_generation_requests on conflict do nothing;
